import HeroSectionV9 from "./components/hero-section-v9"

export default function Page() {
  return (
    <div className="p-6">
      <HeroSectionV9 />
    </div>
  )
}

import HeroContent from "./hero-content"

import type { HeroV9Props } from "../lib/config"

import "../styles/hero-section-v9.css"

export default function HeroSectionV9(props: HeroV9Props) {
  return (
    <section className="py-4 md:py-6 lg:py-8">
      <div className="mx-auto max-w-6xl px-4">
        <HeroContent {...props} />
      </div>
    </section>
  )
}

import CtaButtons from "./cta-buttons"
import ProductPreviewShell from "./product-preview-shell"

import type { HeroV9Props } from "../lib/config"
import { resolveHeroV9Content, resolveHeroV9Preview } from "../lib/config"

export default function HeroContent(props: HeroV9Props) {
  const content = resolveHeroV9Content(props)
  const preview = resolveHeroV9Preview(props.preview)

  return (
    <div className="flex flex-col items-center gap-6 text-center">
      <h1 className="max-w-3xl text-3xl font-medium tracking-tight sm:text-4xl lg:text-5xl lg:leading-[1.15]">
        {content.title}
      </h1>

      <p className="max-w-xl text-base leading-relaxed text-muted-foreground sm:text-lg">
        {content.description}
      </p>

      <CtaButtons
        primaryCta={content.primaryCta}
        secondaryCta={content.secondaryCta}
      />

      <div className="w-full pt-2">
        <ProductPreviewShell preview={preview} />
      </div>
    </div>
  )
}

"use client"

import ActivityPanel from "./activity-panel"
import MetricsRow from "./metrics-row"
import TasksPanel from "./tasks-panel"
import { useLiveDashboardPreview } from "../hooks/use-live-dashboard-preview"

import type { ProductPreviewConfig } from "../lib/config"

export default function ProductPreviewShell({
  preview,
}: {
  preview: ProductPreviewConfig
}) {
  const live = useLiveDashboardPreview(preview)

  return (
    <div
      className="pp-root relative mx-auto w-full max-w-5xl overflow-hidden rounded-xl bg-(--pp-shell-bg) shadow-(--pp-shadow)"
      role="img"
      aria-label="Operations dashboard preview"
    >
      <MetricsRow metrics={live.metrics} />
      <div className="hero-v9-panels grid grid-cols-1 items-stretch lg:grid-cols-2">
        <ActivityPanel
          activity={live.panels.activity}
          live
          pulseKey={live.barsPulseKey}
          taskStates={live.panels.tasks.rows.map((row) => row.state)}
          queuedJobs={live.queuedJobs}
          barPeaks={live.barPeaks}
        />
        <TasksPanel tasks={live.panels.tasks} />
      </div>
    </div>
  )
}

import MetricCard from "./metric-card"

export default function MetricsRow({
  metrics,
}: {
  metrics: ReadonlyArray<{ value: string; label: string; pulseKey: number }>
}) {
  return (
    <div className="hero-v9-metrics relative z-1">
      {metrics.map((metric) => (
        <MetricCard
          key={metric.label}
          value={metric.value}
          label={metric.label}
          pulseKey={metric.pulseKey}
        />
      ))}
    </div>
  )
}

import { cn } from "@/lib/utils"

export default function MetricCard({
  value,
  label,
  pulseKey,
}: {
  value: string
  label: string
  pulseKey?: number
}) {
  return (
    <div className="hero-v9-metric flex flex-col items-center justify-center gap-1 px-3 py-4 text-center">
      <span
        key={`${value}-${pulseKey ?? 0}`}
        className={cn(
          "hero-v9-metric-value text-2xl font-semibold tracking-tight text-foreground tabular-nums",
          pulseKey !== undefined && pulseKey > 0 && "hero-v9-metric-live"
        )}
      >
        {value}
      </span>
      <span className="text-[0.6875rem] uppercase tracking-wider text-muted-foreground">
        {label}
      </span>
    </div>
  )
}

import type { CSSProperties } from "react"

import { cn } from "@/lib/utils"

import type { PreviewStatusState, ProductPreviewConfig } from "../lib/config"

type ActivityConfig = ProductPreviewConfig["panels"]["activity"]

// Integer-only hash (no Math.sin) so the result is bit-identical on the
// server and client — transcendental functions like Math.sin can differ in
// their last bit between engines, which caused hydration mismatches once
// that noise was amplified into CSS custom properties.
function pseudoRandom(seed: number, salt: number): number {
  let x = (seed * 374761393 + salt * 668265263) | 0
  x = (x ^ (x >>> 13)) * 1274126177
  x = (x ^ (x >>> 16)) >>> 0
  return x / 4294967296
}

const QUEUED_BAR_MIN = 3
const QUEUED_BAR_MAX = 14
const QUEUED_JOBS_BASELINE = 20
const QUEUED_JOBS_PER_BAR = 2

// Queued/status bars don't measure anything — their meaning lives in fill
// style (dashed/hollow) and how many of them there are, not in height. They
// share one flat height so they read as a state ledger, not more volume data.
const STATE_ZONE_BAR_HEIGHT = 60

// Scales the real "Queued jobs" count into a bar count, so the backlog the
// chart implies is sitting behind the 4 named automations grows and shrinks
// with the actual metric instead of always looking like exactly 4 jobs.
function queuedBarCountFor(queuedJobs: number): number {
  const scaled = Math.round((queuedJobs - QUEUED_JOBS_BASELINE) / QUEUED_JOBS_PER_BAR)
  return Math.min(QUEUED_BAR_MAX, Math.max(QUEUED_BAR_MIN, scaled))
}

export default function ActivityPanel({
  activity,
  live = false,
  pulseKey,
  taskStates = [],
  queuedJobs = 0,
  barPeaks = [],
}: {
  activity: ActivityConfig
  live?: boolean
  pulseKey?: number
  taskStates?: ReadonlyArray<PreviewStatusState>
  queuedJobs?: number
  barPeaks?: ReadonlyArray<boolean>
}) {
  const lastIndex = activity.bars.length - 1

  // The rightmost bars double as a status readout: one bar per automation
  // in the Status overview table, filled while it's running and hollow
  // once it completes — so "bars filled" tracks "tasks running" 1:1.
  const hasStatusBars = taskStates.length > 0
  const statusBarStart = activity.bars.length - taskStates.length

  // Just before those, a wider band of dashed bars stands in for the rest
  // of the queue that isn't named in the table — its width tracks the real
  // "Queued jobs" metric so the volume chart implies a bigger backlog.
  const queuedBarCount = hasStatusBars ? queuedBarCountFor(queuedJobs) : 0
  const queuedZoneStart = Math.max(0, statusBarStart - queuedBarCount)

  return (
    <div className="hero-v9-activity-panel relative z-1 flex min-h-0 flex-1 flex-col">
      <h3 className="hero-v9-panel-heading shrink-0 px-4 py-2.5 text-[0.6875rem] font-semibold uppercase tracking-widest text-muted-foreground">
        {activity.title}
      </h3>

      <div
        className={cn(
          "hero-v9-activity-chart flex min-h-0 w-full flex-1 items-end justify-between gap-1 px-4 py-3",
          live && "hero-v9-activity-chart-live"
        )}
        aria-hidden
      >
        {activity.bars.map((height, index) => {
          const waveDuration = 1.8 + pseudoRandom(index, 1) * 1.8
          const waveDelay = -(pseudoRandom(index, 2) * waveDuration)
          const isNewest = live && index === lastIndex

          const taskState =
            index >= statusBarStart
              ? taskStates[index - statusBarStart]
              : undefined
          const isCompletedBar = taskState !== undefined && taskState !== "running"
          const isQueuedBar =
            taskState === undefined &&
            index >= queuedZoneStart &&
            index < statusBarStart
          const isStateZoneBar = index >= queuedZoneStart

          return (
            <div
              key={index}
              className={cn(
                "hero-v9-bar w-2 shrink-0 rounded-t-sm",
                live && "hero-v9-bar-live"
              )}
              style={{
                height: `${isStateZoneBar ? STATE_ZONE_BAR_HEIGHT : height}%`,
                animationDelay: live ? `${Math.min(index * 5, 150)}ms` : undefined,
                transitionDelay: live ? `${index * 3}ms` : undefined,
              }}
            >
              <span
                key={isNewest ? pulseKey : undefined}
                className={cn(
                  "block h-full w-full rounded-t-sm",
                  isCompletedBar
                    ? "hero-v9-bar-fill-hollow"
                    : isQueuedBar
                      ? "hero-v9-bar-fill-queued"
                      : cn(
                          "hero-v9-bar-fill",
                          // Accent marks bars that landed as a volume burst,
                          // which is the same event that bumps "Runs
                          // completed" — so the highlight tracks that metric
                          // instead of just whichever bar is tallest.
                          barPeaks[index]
                            ? "bg-(--pp-accent)"
                            : "bg-(--pp-accent-muted)"
                        ),
                  isNewest && !isCompletedBar && !isQueuedBar && "hero-v9-bar-fill-new"
                )}
                style={
                  isQueuedBar
                    ? { animationDelay: `${(index - queuedZoneStart) * 90}ms` }
                    : live && !isCompletedBar
                      ? ({
                          "--wave-duration": `${waveDuration}s`,
                          "--wave-delay": `${waveDelay}s`,
                        } as CSSProperties)
                      : undefined
                }
              />
            </div>
          )
        })}
      </div>
    </div>
  )
}

import { cn } from "@/lib/utils"

import type { PreviewStatusState } from "../lib/config"

export default function StatusChip({
  label,
  state,
}: {
  label: string
  state: PreviewStatusState
}) {
  return (
    <div className="inline-flex items-center gap-1.5">
      <span
        className={cn(
          "relative size-1.5 shrink-0 rounded-full",
          state === "waiting" ? "bg-(--pp-dot-idle)" : "bg-(--pp-accent)",
          state === "running" && "hero-v9-status-live"
        )}
        aria-hidden
      />
      <span
        className={cn(
          "text-xs font-medium transition-colors duration-500",
          state === "waiting" ? "text-muted-foreground" : "text-foreground/80",
          state === "running" && "text-foreground"
        )}
      >
        {label}
      </span>
    </div>
  )
}

"use client"

import { useEffect, useMemo, useState, useSyncExternalStore } from "react"

import type { PreviewStatusState, ProductPreviewConfig } from "../lib/config"

function subscribeReducedMotion(onStoreChange: () => void) {
  const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
  mq.addEventListener("change", onStoreChange)
  return () => mq.removeEventListener("change", onStoreChange)
}

function getReducedMotion() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

function getReducedMotionServer() {
  return false
}

type MetricKind = "k" | "percent" | "minutes" | "integer"

type MetricSeed = {
  label: string
  kind: MetricKind
  value: number
  pulseKey: number
}

type TaskSeed = {
  automation: string
  status: string
  state: PreviewStatusState
  minutesAgo: number
}

type DashboardState = {
  metrics: MetricSeed[]
  bars: number[]
  barPeaks: boolean[]
  barsPulseKey: number
  tasks: TaskSeed[]
  cyclePhase: number
}

export type LiveDashboardPreview = {
  metrics: ReadonlyArray<{ value: string; label: string; pulseKey: number }>
  panels: ProductPreviewConfig["panels"] & {
    tasks: ProductPreviewConfig["panels"]["tasks"] & {
      rows: ReadonlyArray<{
        automation: string
        status: string
        lastRun: string
        state: PreviewStatusState
      }>
    }
  }
  barsPulseKey: number
  barPeaks: ReadonlyArray<boolean>
  queuedJobs: number
}

// Metric order is fixed by heroV9Preview.metrics: Runs completed, Success
// rate, Avg. duration, Queued jobs. These two are referenced by index
// elsewhere so the volume chart can react to and reflect them.
const RUNS_COMPLETED_METRIC_INDEX = 0
const QUEUED_JOBS_METRIC_INDEX = 3

// Each metric ticks on its own randomized cadence so the row reads like a
// live market ticker instead of four numbers changing in lockstep.
const METRIC_CADENCE_MS: ReadonlyArray<readonly [number, number]> = [
  [900, 1600], // Runs completed – fast live counter
  [4400, 6600], // Success rate – slow drift
  [2800, 4200], // Avg. duration – medium pace
  [1500, 2500], // Queued jobs – jumpy, order-book feel
]
const DEFAULT_CADENCE_MS: readonly [number, number] = [2200, 3600]
const BARS_CADENCE_MS: readonly [number, number] = [1000, 1800]
const TASKS_CADENCE_MS: readonly [number, number] = [2800, 4200]

function randomDelay([min, max]: readonly [number, number]): number {
  return min + Math.random() * (max - min)
}

function detectMetricKind(value: string): MetricKind {
  if (value.includes("%")) return "percent"
  if (/min/i.test(value)) return "minutes"
  if (/k/i.test(value)) return "k"
  return "integer"
}

function parseMetricValue(value: string, kind: MetricKind): number {
  const numeric = Number.parseFloat(value.replace(/[^\d.]/g, ""))
  if (kind === "k") return numeric * 1000
  return numeric
}

function formatMetricValue(value: number, kind: MetricKind): string {
  switch (kind) {
    case "k":
      return `${(value / 1000).toFixed(1)}K`
    case "percent":
      return `${value.toFixed(1)}%`
    case "minutes":
      return `${value.toFixed(1)} Min`
    default:
      return `${Math.round(value)}`
  }
}

function formatLastRun(minutesAgo: number): string {
  if (minutesAgo <= 0) return "just now"
  if (minutesAgo === 1) return "1 min ago"
  return `${minutesAgo} min ago`
}

function seedMetrics(metrics: ProductPreviewConfig["metrics"]): MetricSeed[] {
  return metrics.map((metric) => {
    const kind = detectMetricKind(metric.value)
    return {
      label: metric.label,
      kind,
      value: parseMetricValue(metric.value, kind),
      pulseKey: 0,
    }
  })
}

function seedTasks(
  rows: ProductPreviewConfig["panels"]["tasks"]["rows"]
): TaskSeed[] {
  return rows.map((row) => ({
    automation: row.automation,
    status: row.status,
    state: row.state,
    minutesAgo: Number.parseInt(row.lastRun, 10) || 1,
  }))
}

function tickMetricValue(metric: MetricSeed): number {
  let next = metric.value

  switch (metric.kind) {
    case "k":
      next += 3 + Math.random() * 7
      break
    case "percent":
      next += Math.random() > 0.65 ? -0.1 : 0.05
      next = Math.min(99.9, Math.max(98.4, next))
      break
    case "minutes":
      next += (Math.random() - 0.5) * 0.12
      next = Math.min(2.2, Math.max(1.1, next))
      break
    default:
      next += Math.floor(Math.random() * 3) - 1
      next = Math.max(24, next)
      break
  }

  return next
}

// Only bumps pulseKey when the *displayed* value actually changes, so a
// metric card doesn't replay its tick animation on ticks that move the raw
// number by an amount too small to show up in the formatted text.
function applyMetricValue(metric: MetricSeed, value: number): MetricSeed {
  const changed =
    formatMetricValue(value, metric.kind) !==
    formatMetricValue(metric.value, metric.kind)

  return {
    ...metric,
    value,
    pulseKey: changed ? metric.pulseKey + 1 : metric.pulseKey,
  }
}

const BARS_MIN = 15
const BARS_MAX = 98
const BARS_BASELINE = 58

type BarEvent = "burst" | "lull" | "normal"

function clampBar(value: number): number {
  return Math.min(BARS_MAX, Math.max(BARS_MIN, Math.round(value)))
}

function nextBarTick(bars: ReadonlyArray<number>): { value: number; event: BarEvent } {
  const last = bars[bars.length - 1]
  const prev = bars[bars.length - 2] ?? last
  const momentum = last - prev

  const roll = Math.random()

  if (roll < 0.06) {
    // a batch job lands: quick burst in run volume
    return { value: clampBar(last + 14 + Math.random() * 22), event: "burst" }
  }

  if (roll < 0.12) {
    // queue drains out: sudden lull
    return { value: clampBar(last - (14 + Math.random() * 22)), event: "lull" }
  }

  // otherwise drift with some carried momentum, gently pulled back to baseline
  const meanPull = (BARS_BASELINE - last) * 0.08
  const carried = momentum * 0.35
  const noise = (Math.random() - 0.5) * 16
  return { value: clampBar(last + meanPull + carried + noise), event: "normal" }
}

// Peaks shift through the window alongside their bar so a burst stays
// marked as it scrolls left, then falls off once it exits the window —
// this is what ties the accent bars to "Runs completed" (see below).
function tickBars(
  bars: ReadonlyArray<number>,
  peaks: ReadonlyArray<boolean>
): { bars: number[]; peaks: boolean[]; event: BarEvent } {
  const tick = nextBarTick(bars)
  return {
    bars: [...bars.slice(1), tick.value],
    peaks: [...peaks.slice(1), tick.event === "burst"],
    event: tick.event,
  }
}

// Bumps a single metric out of its own cadence, so a notable moment in the
// volume chart (a burst or a lull) visibly ripples into the metrics row
// instead of the two panels just simulating side by side.
function bumpMetric(
  metrics: MetricSeed[],
  index: number,
  nextValue: (value: number) => number
): MetricSeed[] {
  const current = metrics[index]
  if (!current) return metrics
  const next = metrics.slice()
  next[index] = applyMetricValue(current, nextValue(current.value))
  return next
}

// Reacts to a volume burst by pulling a currently idle automation into
// "Running" early, tying the Status overview table to the volume chart.
function startIdleTask(tasks: TaskSeed[]): TaskSeed[] {
  const candidateIndex = tasks.findIndex(
    (task, index) => index !== 1 && task.state !== "running"
  )
  if (candidateIndex === -1) return tasks

  const next = tasks.slice()
  next[candidateIndex] = {
    ...next[candidateIndex],
    status: "Running",
    state: "running",
    minutesAgo: 0,
  }
  return next
}

function tickTasks(tasks: TaskSeed[], cyclePhase: number): TaskSeed[] {
  return tasks.map((task, index) => {
    let { status, state, minutesAgo } = task

    minutesAgo = state === "running" ? minutesAgo : minutesAgo + 1

    if (index === 1) {
      return { ...task, status, state, minutesAgo: Math.max(0, minutesAgo - 1) }
    }

    if (cyclePhase === 0 && index === 2 && state !== "running") {
      status = "Running"
      state = "running"
      minutesAgo = 0
    } else if (cyclePhase === 2 && index === 2 && state === "running") {
      status = "Completed"
      state = "success"
      minutesAgo = 1
    } else if (cyclePhase === 4 && index === 0 && state !== "running") {
      status = "Running"
      state = "running"
      minutesAgo = 0
    } else if (cyclePhase === 6 && index === 0 && state === "running") {
      status = "Completed"
      state = "success"
      minutesAgo = 1
    }

    return { ...task, status, state, minutesAgo }
  })
}

function seedState(config: ProductPreviewConfig): DashboardState {
  const bars = config.panels.activity.bars
  const seedMaxIndex = bars.reduce(
    (best, height, index) => (height > bars[best] ? index : best),
    0
  )

  return {
    metrics: seedMetrics(config.metrics),
    bars: [...bars],
    barPeaks: bars.map((_, index) => index === seedMaxIndex),
    barsPulseKey: 0,
    tasks: seedTasks(config.panels.tasks.rows),
    cyclePhase: 0,
  }
}

function buildPreview(
  config: ProductPreviewConfig,
  state: DashboardState
): LiveDashboardPreview {
  return {
    metrics: state.metrics.map((metric) => ({
      label: metric.label,
      value: formatMetricValue(metric.value, metric.kind),
      pulseKey: metric.pulseKey,
    })),
    panels: {
      activity: {
        title: config.panels.activity.title,
        bars: state.bars,
      },
      tasks: {
        legendTitle: config.panels.tasks.legendTitle,
        legend: config.panels.tasks.legend,
        tableTitle: config.panels.tasks.tableTitle,
        rows: state.tasks.map((task) => ({
          automation: task.automation,
          status: task.status,
          state: task.state,
          lastRun: formatLastRun(task.minutesAgo),
        })),
      },
    },
    barsPulseKey: state.barsPulseKey,
    barPeaks: state.barPeaks,
    queuedJobs: state.metrics[QUEUED_JOBS_METRIC_INDEX]?.value ?? 0,
  }
}

export function useLiveDashboardPreview(
  config: ProductPreviewConfig
): LiveDashboardPreview {
  const reducedMotion = useSyncExternalStore(
    subscribeReducedMotion,
    getReducedMotion,
    getReducedMotionServer
  )

  const [state, setState] = useState<DashboardState>(() => seedState(config))

  useEffect(() => {
    if (reducedMotion) return

    const timeouts = new Set<number>()

    function scheduleMetric(index: number) {
      const cadence = METRIC_CADENCE_MS[index] ?? DEFAULT_CADENCE_MS
      const id = window.setTimeout(() => {
        timeouts.delete(id)
        setState((prev) => {
          const current = prev.metrics[index]
          if (!current) return prev
          const metrics = prev.metrics.slice()
          metrics[index] = applyMetricValue(current, tickMetricValue(current))
          return { ...prev, metrics }
        })
        scheduleMetric(index)
      }, randomDelay(cadence))
      timeouts.add(id)
    }

    function scheduleBars() {
      const id = window.setTimeout(() => {
        timeouts.delete(id)
        setState((prev) => {
          const { bars, peaks, event } = tickBars(prev.bars, prev.barPeaks)
          let metrics = prev.metrics
          let tasks = prev.tasks

          if (event === "burst") {
            // a burst in volume reads as a wave of runs landing at once
            metrics = bumpMetric(
              metrics,
              RUNS_COMPLETED_METRIC_INDEX,
              (value) => value + 40 + Math.random() * 70
            )
            metrics = bumpMetric(metrics, QUEUED_JOBS_METRIC_INDEX, (value) =>
              Math.max(24, value - (3 + Math.random() * 6))
            )
            tasks = startIdleTask(tasks)
          } else if (event === "lull") {
            // a lull means fewer runs draining the queue, so it backs up
            metrics = bumpMetric(
              metrics,
              QUEUED_JOBS_METRIC_INDEX,
              (value) => value + 2 + Math.random() * 5
            )
          }

          return {
            ...prev,
            bars,
            barPeaks: peaks,
            barsPulseKey: prev.barsPulseKey + 1,
            metrics,
            tasks,
          }
        })
        scheduleBars()
      }, randomDelay(BARS_CADENCE_MS))
      timeouts.add(id)
    }

    function scheduleTasks() {
      const id = window.setTimeout(() => {
        timeouts.delete(id)
        setState((prev) => {
          const cyclePhase = (prev.cyclePhase + 1) % 8
          return { ...prev, tasks: tickTasks(prev.tasks, cyclePhase), cyclePhase }
        })
        scheduleTasks()
      }, randomDelay(TASKS_CADENCE_MS))
      timeouts.add(id)
    }

    config.metrics.forEach((_, index) => scheduleMetric(index))
    scheduleBars()
    scheduleTasks()

    return () => {
      timeouts.forEach((id) => window.clearTimeout(id))
    }
  }, [config, reducedMotion])

  return useMemo(() => buildPreview(config, state), [config, state])
}

export type HeroV9Cta = {
  label: string
  href: string
}

export type PreviewStatusState = "success" | "running" | "waiting"

export type HeroV9Content = {
  title: string
  description: string
  primaryCta: HeroV9Cta
  secondaryCta: HeroV9Cta
}

export type ProductPreviewConfig = {
  metrics: ReadonlyArray<{ value: string; label: string }>
  panels: {
    activity: {
      title: string
      bars: ReadonlyArray<number>
    }
    tasks: {
      legendTitle: string
      legend: ReadonlyArray<{ label: string; state: PreviewStatusState }>
      tableTitle: string
      rows: ReadonlyArray<{
        automation: string
        status: string
        lastRun: string
        state: PreviewStatusState
      }>
    }
  }
}

export const heroV9Content: HeroV9Content = {
  title: "Visual Automation for Modern Teams",
  description:
    "Design playbooks once, schedule recurring work, and keep every operation visible in one place.",
  primaryCta: { label: "View pricing", href: "#" },
  secondaryCta: { label: "Join waitlist", href: "#" },
}

export const heroV9Preview: ProductPreviewConfig = {
  metrics: [
    { value: "12.4K", label: "Runs completed" },
    { value: "98.9%", label: "Success rate" },
    { value: "1.5 Min", label: "Avg. duration" },
    { value: "28", label: "Queued jobs" },
  ],
  panels: {
    activity: {
